fn writer_emits_bare_when_enabled() {", "newText": "#[test]
fn reader_preserves_yaml_list_in_bare_frontmatter() {
    setup();
    // Regression: indented YAML list items (e.g. `  - foo`) used to be
    // stripped during the bare→fenced rewrap, breaking metadata queries
    // like `--meta depends=foo` against bare-frontmatter documents.
    let wrapped = liwe::markdown::wrap_bare_frontmatter(indoc! {"
        title: Foo
        depends:
          - foo
          - bar

        # Body
        "});
    assert!(wrapped.contains("  - foo"), "list item dropped: {}", wrapped);
