    let parsed: serde_yaml::Value =
        serde_yaml::from_str(wrapped.split("---").nth(1).unwrap()).unwrap();
    let depends = parsed.get("depends").and_then(|v| v.as_sequence()).unwrap();
    assert_eq!(depends.len(), 2);
    assert_eq!(depends[0].as_str(), Some("foo"));
}

